SELECT     soh.ITEM AS \"Item ID\",     im.ITEM_DESC AS \"Item Description\",     im.DEPT AS \"Department Number\",     d.DEPT_NAME AS \"Department Name\",     soh.LOC AS \"Location ID\",     soh.LOC_TYPE AS \"Location Type\",     CASE soh.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END AS \"Location Name\",     soh.STOCK_ON_HAND AS \"Stock on Hand\",     soh.IN_TRANSIT_QTY AS \"In Transit Quantity\",     soh.LAST_SOLD AS \"Last Sold Date\" FROM rds_wv_item_loc_soh soh INNER JOIN rds_wv_item_master im ON soh.ITEM = im.ITEM LEFT JOIN rds_wv_deps d ON im.DEPT = d.DEPT LEFT JOIN rds_wv_store st ON soh.LOC = st.STORE AND soh.LOC_TYPE = 'S' LEFT JOIN rds_wv_wh wh ON soh.LOC = wh.WH AND soh.LOC_TYPE = 'W' WHERE soh.STOCK_ON_HAND &gt; 0 AND NOT EXISTS (

